const AdmZip = require('adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.readAsText('word/document.xml');

// Parse out text content from the XML
const paragraphs = xml.split(/<\/w:p>/);
const lines = paragraphs.map(p => {
  const texts = [];
  const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let m;
  while ((m = re.exec(p)) !== null) {
    texts.push(m[1]);
  }
  return texts.join('');
}).filter(l => l.length > 0 || true);

// Print, keeping blank lines for paragraph breaks
lines.forEach(l => console.log(l));
"
